class Solution:
    def countPalindromicSubsequences(self, s: str) -> int:
        seen = set()
        n = len(s)
        for mask in range(1, 1 << n):
            t = []
            for i in range(n):
                if mask & (1 << i):
                    t.append(s[i])
            word = "".join(t)
            if word == word[::-1]:
                seen.add(word)
        return len(seen) % 1000000007

