class Solution:
    def countPalindromicSubsequences(self, s):
        mod = 1000000007
        n = len(s)
        dp = [[0] * n for _ in range(n)]
        for i in range(n):
            dp[i][i] = 1
        for length in range(2, n + 1):
            for l in range(n - length + 1):
                r = l + length - 1
                if s[l] != s[r]:
                    dp[l][r] = dp[l + 1][r] + dp[l][r - 1] - dp[l + 1][r - 1]
                else:
                    lo, hi = l + 1, r - 1
                    while lo <= hi and s[lo] != s[l]:
                        lo += 1
                    while lo <= hi and s[hi] != s[l]:
                        hi -= 1
                    if lo > hi:
                        dp[l][r] = 2 * dp[l + 1][r - 1] + 2
                    elif lo == hi:
                        dp[l][r] = 2 * dp[l + 1][r - 1] + 1
                    else:
                        dp[l][r] = 2 * dp[l + 1][r - 1] - dp[lo + 1][hi - 1]
                dp[l][r] %= mod
        return dp[0][n - 1]

solutions.optimal:
class Solution:
    def countPalindromicSubsequences(self, s):
        mod = 1000000007
        n = len(s)
        chars = "abcd"
        dp = [[[0] * 4 for _ in range(n)] for _ in range(n)]
        for i, ch in enumerate(s):
            dp[i][i][chars.index(ch)] = 1
        for length in range(2, n + 1):
            for l in range(n - length + 1):
                r = l + length - 1
                for k, ch in enumerate(chars):
                    if s[l] == ch and s[r] == ch:
                        dp[l][r][k] = 2 + sum(dp[l + 1][r - 1])
                    elif s[l] == ch:
                        dp[l][r][k] = dp[l][r - 1][k]
                    elif s[r] == ch:
                        dp[l][r][k] = dp[l + 1][r][k]
                    else:
                        dp[l][r][k] = dp[l + 1][r - 1][k]
                    dp[l][r][k] %= mod
        return sum(dp[0][n - 1]) % mod

